import assert from "node:assert/strict";
import { readFile } from "node:fs/promises";
import { runInNewContext } from "node:vm";
import ts from "typescript";

const [understand, issues, recap, types] = await Promise.all([
  readFile(new URL("../components/workspace/UnderstandPanel.tsx", import.meta.url), "utf8"),
  readFile(new URL("../components/workspace/IssueNavigator.tsx", import.meta.url), "utf8"),
  readFile(new URL("../components/workspace/ChangeRecap.tsx", import.meta.url), "utf8"),
  readFile(new URL("../lib/workspaceTypes.ts", import.meta.url), "utf8"),
]);

assert.match(understand, /Current business question/, "Understand must lead with the canonical business question");
assert.match(understand, /Useful current answer/, "Understand must keep an answer-first reading surface");
assert.match(understand, /import ReactMarkdown from "react-markdown"/, "saved answers must use the established Markdown renderer");
assert.match(understand, /remarkPlugins=\{\[remarkGfm\]\}/, "saved answers must support standard GitHub-flavored Markdown");
assert.match(understand, /const LONG_ANSWER_CHARACTER_LIMIT = 1200/, "long saved answers need a bounded initial reading surface");
assert.match(understand, /function longAnswerPreview\(answer: string\)/, "a long-answer preview must retain original saved text rather than invent a summary");
assert.match(understand, /answer\.split\(\/\(\?<=\\n\)\//, "long-answer previews must consider complete Markdown lines");
assert.match(understand, /\^\\s\*\(`\{3,\}\|~\{3,\}\)/, "long-answer previews must not end inside fenced code");
const previewModule = { exports: {} as { longAnswerPreview: (answer: string) => { text: string; earlierText?: string } } };
runInNewContext(ts.transpileModule(understand, {
  fileName: "UnderstandPanel.tsx",
  compilerOptions: { module: ts.ModuleKind.CommonJS, target: ts.ScriptTarget.ES2022, jsx: ts.JsxEmit.ReactJSX, esModuleInterop: true },
}).outputText, { exports: previewModule.exports, require: () => ({}) });
for (const reference of ["[Saved authority][source]", "![Supplied diagram][source]", "[source][]"]) {
  const answer = `${reference}\n\n${"Keep the source qualification. ".repeat(60)}\n\nCurrent answer\n\nApply that qualification.\n\n[source]: https://example.test/supplied-source "Original title"\n`;
  const preview = previewModule.exports.longAnswerPreview(answer);
  assert.equal(preview.text, answer, "reference-style Markdown and its distant definition must stay complete and in source order");
  assert.equal(preview.earlierText, undefined, "a referenced answer must not split its definition from the original text");
}
assert.match(understand, /<ReactMarkdown components=\{answerMarkdownComponents\} remarkPlugins=\{\[remarkGfm\]\}>\{visibleAnswer\}<\/ReactMarkdown>/, "the visible saved answer must render Markdown rather than raw syntax");
assert.match(understand, /const preview = answerExpanded \|\| !answerIsLong \? \{ text: savedAnswer\.text \} : longAnswerPreview\(savedAnswer\.text\)/, "expanding a long answer must restore the complete saved Markdown");
assert.match(understand, /const visibleAnswer = preview\.text/, "the renderer must receive the preview text, including the complete expanded answer");
assert.match(understand, /const previewIsOneLongBlock = answerIsLong && !answerExpanded && visibleAnswer === savedAnswer\.text/, "only a long one-block answer may use the fixed-height disclosure");
assert.match(understand, /maxHeight: "30rem", overflow: "hidden"/, "one long Markdown block must use a bounded disclosure instead of a character cut");
assert.doesNotMatch(understand, /answer\.slice\(0, LONG_ANSWER_CHARACTER_LIMIT\)/, "a long answer must never use a hard character cut");
assert.match(understand, /table: \(\{ children \}: \{ children\?: React\.ReactNode \}\)[\s\S]*?overflowX: "auto"/, "wide Markdown tables must scroll within the reading card");
assert.match(understand, /pre: \(\{ children \}: \{ children\?: React\.ReactNode \}\)[\s\S]*?overflowX: "auto"/, "wide Markdown code blocks must scroll within the reading card");
assert.match(understand, /aria-controls=\{answerId\} aria-expanded=\{answerExpanded\}/, "the long-answer control must expose its expanded state to assistive technology");
assert.match(understand, /Show less[\s\S]*?Read full answer/, "a long answer must provide both expand and collapse actions");
assert.match(understand, /Proposed reframe[\s\S]*?Apply[\s\S]*?Reject/, "a proposed reframe needs explicit durable actions");
assert.match(understand, /Earlier questions[\s\S]*?Based on an earlier question/, "question history must name earlier scope");
assert.match(understand, /Answer[\s\S]*?Explore why[\s\S]*?Leave open/, "supporting questions need all three actions");
assert.match(understand, /question\.state !== "answered"/, "left-open questions must keep Answer and Explore why controls");
assert.match(understand, /Fact saved\. Question update not saved\./, "partial answer receipts must be truthful");
assert.match(understand, /receiptClass\(noticeState\)/, "a not-saved receipt must not use the healthy success treatment");
assert.match(understand, /baseRevision: currentQuestion\.revision/, "question editing must capture the revision at edit start");
assert.match(understand, /expected_revision: draft\.baseRevision/, "question saves must use the captured revision");
assert.match(understand, /Rebase my edit/, "a changed question needs an explicit rebase choice");
assert.match(understand, /Business question<\/span><textarea className="text-input prose" disabled=\{busy\}/, "the business-question input must lock while its successful save can clear the submitted draft");
assert.match(understand, /Material facts/, "material facts must remain visible");
assert.match(understand, /Business context/, "business context must remain visible");
assert.match(understand, /Sources and actions/, "source actions must be discoverable");
assert.match(understand, /source_action_key: actionKey/, "direct actions must retain a retry key");
assert.match(understand, /const \[answeringIds, setAnsweringIds\] = useState<string\[\]>\(\[\]\)/, "each supporting answer needs independent pending state");
assert.match(understand, /answeringIds\.includes\(question\.question_id\)/, "one answer save must keep its own field locked while another runs");
assert.match(understand, /filter\(\(questionId\) => questionId !== question\.question_id\)/, "finishing one answer save must not clear another pending answer");
assert.doesNotMatch(understand, /Saved\./, "the panel must not claim a generic saved state before examining the receipt");
assert.doesNotMatch(understand, /ChatPanel|<textarea[^>]*placeholder="Ask/, "Understand must not create a second chat composer or history");

assert.match(issues, /baseRevision: issuesRevision/, "issue editing must capture the revision at edit start");
assert.match(issues, /expected_revision: draft\.baseRevision/, "each issue save must use its captured revision");
assert.match(issues, /Rebase my edits/, "a changed issue needs an explicit rebase choice");
assert.match(issues, /Issue change was not saved\. Your edits are retained\./, "failed issue saves must keep the local draft");
assert.match(issues, /hasOwnProperty\.call\(changes, key\)/, "clearing a parent must retain the draft null instead of falling back to the old parent");
assert.doesNotMatch(issues, /className=\{selected \? "wash-attention"/, "selection must use a neutral border, not attention color");
assert.match(issues, /stateLabel\(issue\.lawyer_state\)/, "the visible state label must remain the saved state while an edit is dirty");
assert.match(issues, /const \[savingIds, setSavingIds\] = useState<string\[\]>\(\[\]\)/, "each issue save needs independent pending state");
assert.match(issues, /savingIds\.includes\(issue\.issue_id\)/, "one issue save must keep its own fields locked while another runs");
assert.match(issues, /filter\(\(issueId\) => issueId !== issue\.issue_id\)/, "finishing one issue save must not clear another pending issue");
assert.match(issues, /Issue title[\s\S]*?Parent issue[\s\S]*?Lawyer state/, "issues need title, parent, and lawyer-state editing");
assert.match(issues, /<option value="open">Open<\/option>[\s\S]*?<option value="explored">Explored<\/option>[\s\S]*?<option value="set_aside">Set aside<\/option>/, "lawyer states must be explicit");

assert.match(recap, /Some optional output files could not be read\./, "recap must warn without hiding saved work");
assert.match(recap, /await onMarkSeen\(currentRecap\.current_revision\)/, "mark seen must await the durable callback");
assert.match(recap, /savedRevision === currentRecap\.current_revision/, "a new recap revision must reset the local seen state");
assert.match(recap, /disabled=\{saving \|\| seen\}/, "mark seen must re-enable for a newer recap revision");
assert.match(recap, /Changes were not marked seen\. You can retry\./, "failed mark-seen writes must be retryable");
assert.match(recap, /Open \{path\.split/, "saved output links must stay usable");

assert.match(types, /onMarkSeen: \(revision: string\) => Promise<void>/, "Understand needs the real mark-seen callback for recap");
for (const source of [understand, issues, recap]) assert.doesNotMatch(source, /#[0-9a-fA-F]{3,8}/, "workspace panels must use shared semantic color tokens");

const recapIsSeen = (savedRevision: string | null, currentRevision: string) => savedRevision === currentRevision;
assert.equal(recapIsSeen("rev-1", "rev-1"), true, "the saved recap revision is seen");
assert.equal(recapIsSeen("rev-1", "rev-2"), false, "a newer recap must become actionable again");
const longMarkdown = "## Recommendation\n\nUse the revised notice.\n\n- Keep the current scope\n- Record the exception\n\n".repeat(30);
assert.ok(longMarkdown.length > 1200, "the long-answer fixture exceeds the disclosure limit");
assert.match(longMarkdown, /## Recommendation[\s\S]*?- Keep the current scope/, "the long-answer fixture includes Markdown that must render as structure");
const oneBlockMarkdown = `[Saved analysis](https://example.test/${"scope-".repeat(350)})`;
assert.ok(oneBlockMarkdown.length > 1200, "the single-block fixture exceeds the disclosure limit");
assert.match(oneBlockMarkdown, /^\[[^\]]+\]\(https:\/\//, "the single-block fixture starts with a complete Markdown link that must not be cut");
const shortTallMarkdown = "- item\n".repeat(80);
assert.ok(shortTallMarkdown.length < 1200, "the short tall fixture stays below the long-answer disclosure threshold");
const draftValue = (changes: { parent_issue_id?: string | null }, fallback: string | null) => Object.prototype.hasOwnProperty.call(changes, "parent_issue_id") ? changes.parent_issue_id : fallback;
assert.equal(draftValue({ parent_issue_id: null }, "ISS-parent"), null, "an explicit parent clear must not revert to the old parent");
const beginPending = (pending: string[], id: string) => pending.includes(id) ? pending : [...pending, id];
const endPending = (pending: string[], id: string) => pending.filter((pendingId) => pendingId !== id);
let pending = beginPending([], "A");
pending = beginPending(pending, "B");
pending = endPending(pending, "B");
assert.deepEqual(pending, ["A"], "when B finishes first, deferred A must remain locked");
pending = endPending(pending, "A");
assert.deepEqual(pending, [], "both controls unlock only after both deferred saves finish");

console.log("Workspace Understand checks passed.");

frontend/scripts/check-review-layout.ts:
import assert from "node:assert/strict";
import { readFile } from "node:fs/promises";
import { runInNewContext } from "node:vm";
import ts from "typescript";

type ElementNode = { type: unknown; props: Record<string, unknown> };
type ModuleExports = Record<string, unknown> & { default?: (props: Record<string, unknown>) => ElementNode };

function jsx(type: unknown, props: Record<string, unknown> | null): ElementNode {
  return { type, props: props ?? {} };
}

function loadComponent(source: string, fileName: string, extraModules: Record<string, unknown> = {}, stateValues: unknown[] = []): ModuleExports {
  const module = { exports: {} as ModuleExports };
  const output = ts.transpileModule(source, {
    fileName,
    compilerOptions: { module: ts.ModuleKind.CommonJS, target: ts.ScriptTarget.ES2022, jsx: ts.JsxEmit.ReactJSX, esModuleInterop: true },
  }).outputText;
  runInNewContext(output, {
    exports: module.exports,
    module,
    require: (name: string) => {
      if (name === "react/jsx-runtime") return { Fragment: "Fragment", jsx, jsxs: jsx };
      if (name === "react") { let stateIndex = 0; return { useId: () => `review-detail-${stateIndex}`, useState: (value: unknown) => [stateIndex < stateValues.length ? stateValues[stateIndex++] : (stateIndex++, value), () => undefined] }; }
      if (name in extraModules) return extraModules[name];
      return {};
    },
  });
  return module.exports;
}

function children(node: unknown): unknown[] {
  if (node === null || node === undefined || typeof node === "boolean") return [];
  if (Array.isArray(node)) return node.flatMap(children);
  if (typeof node !== "object") return [];
  const element = node as ElementNode;
  if (typeof element.type === "function") return children(element.type(element.props));
  return [element, ...children(element.props.children)];
}

function textContent(node: unknown): string {
  if (node === null || node === undefined || typeof node === "boolean") return "";
  if (typeof node === "string" || typeof node === "number") return String(node);
  if (Array.isArray(node)) return node.map(textContent).join("");
  const element = node as ElementNode;
  if (typeof element.type === "function") return textContent(element.type(element.props));
  return textContent(element.props.children);
}

const [workItemSource, orientationSource] = await Promise.all([
  readFile(new URL("../components/workspace/WorkItemSummary.tsx", import.meta.url), "utf8"),
  readFile(new URL("../components/workspace/OrientationSummary.tsx", import.meta.url), "utf8"),
]);

const workItemModule = loadComponent(workItemSource, "WorkItemSummary.tsx");
const previewIssueTitle = workItemModule.previewIssueTitle as (title: string, limit?: number) => string;
const reviewStatePresentation = workItemModule.reviewStatePresentation as (state: string) => { label: string; className: string; washClassName: string };
const WorkItemSummary = workItemModule.default!;

const fullTitle = "Whether the learning service may collect a very long set of account, device, and classroom details before a teacher confirms the age of each learner";
const preview = previewIssueTitle(fullTitle, 72);
assert.ok(preview.length <= 73 && preview.endsWith("…"), "a long issue gets a bounded word-aware label");
assert.equal(previewIssueTitle("  Keep   the original words  "), "Keep the original words");
assert.equal(JSON.stringify(reviewStatePresentation("needs_attention")), JSON.stringify({ label: "Needs attention", className: "state-attention", washClassName: "wash-attention" }));
assert.equal(JSON.stringify(reviewStatePresentation("agent_work")), JSON.stringify({ label: "Agent work", className: "state-agent", washClassName: "wash-agent" }));
assert.equal(JSON.stringify(reviewStatePresentation("complete")), JSON.stringify({ label: "Complete", className: "state-healthy", washClassName: "wash-healthy" }));
assert.equal(JSON.stringify(reviewStatePresentation("overdue")), JSON.stringify({ label: "Overdue", className: "state-failure", washClassName: "wash-failure" }));

let openedIssue = "";
let closeCount = 0;
const workTree = WorkItemSummary({
  item: { issue_id: "ISS-AGE", reason: "The answer changes the launch path.", actor: "Alex Morgan", action_label: "Review the learner age and consent path before launch", state: "needs_attention", saved_order: 1 },
  issue: { issue_id: "ISS-AGE", title: fullTitle },
  onOpenIssue: (issueId: string) => { openedIssue = issueId; },
  onClosePanel: () => { closeCount += 1; },
});
const workNodes = children(workTree) as ElementNode[];
const workButtons = workNodes.filter((node) => node.type === "button");
assert.equal(textContent(workTree).includes(fullTitle), true, "the full saved issue wording remains in the rendered disclosure");
assert.equal(textContent(workTree).includes("Needs attention"), true, "the attention color has a visible state word");
assert.equal(textContent(workTree).includes("Owner: Alex Morgan"), true, "the state and owner row names its owner");
assert.equal(workButtons.length, 2, "the banner has one work action and one presentation action");
(workButtons[0].props.onClick as () => void)();
assert.equal(openedIssue, "ISS-AGE", "the work action opens the frozen issue identity");
(workButtons[1].props.onClick as () => void)();
assert.equal(closeCount, 1, "Close panel calls only the presentation callback");
assert.equal(openedIssue, "ISS-AGE", "closing the panel does not complete or retarget work");
assert.equal(textContent(workTree).includes("Issue to review"), true, "the title row is visibly labeled");
for (const label of ["State and owner", "Review actions"]) assert.equal(workNodes.some((node) => node.props["aria-label"] === label), true, `${label} remains a separate row`);

const orientationModule = loadComponent(orientationSource, "OrientationSummary.tsx", {
  "@/lib/orientationPresentation": {
    previewOrientationQuestion: (question: string) => question.length > 40 ? `${question.slice(0, 39)}…` : question,
    visibleOrientationActions: () => ({ primary: null, secondary: [] }),
    actionOwnerText: () => null,
    actionStateWord: () => "Ready",
  },
  "./WorkItemSummary": { default: WorkItemSummary },
});
const OrientationSummary = orientationModule.default!;
const compactAnswerPreview = orientationModule.compactAnswerPreview as (answer: string, limit?: number) => { text: string; shortened: boolean; plainText: boolean };
const sectionAnswer = "Let me examine the facts.\n\n### Bottom line\nThe launch needs an audience review [source:SRC-1|Section 2].\n\n### Further limits\nThe operator status remains unknown.";
assert.match(compactAnswerPreview(sectionAnswer).text, /^The launch needs an audience review/);
assert.ok(compactAnswerPreview(sectionAnswer).text.includes("[source:SRC-1|Section 2]"));
assert.ok(compactAnswerPreview(sectionAnswer).shortened, "the full original remains available through expansion");
assert.match(compactAnswerPreview("```md\n### Bottom line\nFake answer\n```\n\nActual text").text, /^```md/, "a fenced heading cannot select a new answer");
let reviewOpen = "";
let showedAll = 0;
const orientationTree = OrientationSummary({
  question: { question_id: "Q-1", revision: "q1", text: "May the learning service launch before the school confirms the learner age and consent route?" },
  shortAnswer: "Launch only after the open age question is answered.",
  qualification: "The school contract has not been supplied.",
  reviewItems: [{ issue_id: "ISS-AGE", reason: "The answer controls the consent path.", actor: "Alex Morgan", action_label: "Review age question", state: "needs_attention", saved_order: 1 }],
  allIssueCount: 6,
  onOpenIssue: (issueId: string) => { reviewOpen = issueId; },
  onShowAllIssues: () => { showedAll += 1; },
});
const orientationNodes = children(orientationTree) as ElementNode[];
const orientationButtons = orientationNodes.filter((node) => node.type === "button");
assert.match(textContent(orientationTree), /Business question[\s\S]*Working answer · Agent work[\s\S]*Qualification[\s\S]*One next action/, "orientation keeps question, answer, qualification, and one action in reading order");
assert.equal(textContent(orientationTree).includes("All issues (6)"), true, "the complete issue list remains one action away");
(orientationButtons.find((button) => textContent(button) === "Review age question")!.props.onClick as () => void)();
assert.equal(reviewOpen, "ISS-AGE");
(orientationButtons.find((button) => textContent(button) === "All issues (6)")!.props.onClick as () => void)();
assert.equal(showedAll, 1);

const supportedOpening = `The service can launch only after the school confirms the age route [source:SRC-COPPA|16 C.F.R. 312.2].\n\n${"Later analysis must stay below the fold. ".repeat(40)}`;
const supportedPreview = compactAnswerPreview(supportedOpening);
assert.equal(supportedPreview.text, "The service can launch only after the school confirms the age route [source:SRC-COPPA|16 C.F.R. 312.2].", "a complete opening paragraph keeps its exact source marker");
assert.equal(supportedPreview.plainText, false, "a complete supported paragraph remains available to the source renderer");
let collapsedRenderedText = "";
const longOrientationTree = OrientationSummary({
  question: { question_id: "Q-2", revision: "q2", text: "May the service launch?" },
  shortAnswer: supportedOpening,
  qualification: "The school confirmation remains open.",
  reviewItems: [{ issue_id: "ISS-AGE", reason: "The launch condition is open.", actor: "Alex Morgan", action_label: "Review launch condition", state: "needs_attention", saved_order: 1 }],
  allIssueCount: 1,
  onOpenIssue: () => undefined,
  onShowAllIssues: () => undefined,
  renderAnswer: (answer: string) => { collapsedRenderedText = answer; return jsx("a", { href: "#source", children: answer }); },
});
const longOrientationText = textContent(longOrientationTree);
assert.equal(collapsedRenderedText, supportedPreview.text, "the collapsed source renderer receives only the complete preview");
assert.equal(longOrientationText.includes("Later analysis must stay below the fold"), false, "later answer paragraphs are not mounted while collapsed");
assert.match(longOrientationText, /Read full answer[\s\S]*Qualification[\s\S]*One next action/, "the next action remains in the collapsed first-screen tree");
assert.equal((children(longOrientationTree) as ElementNode[]).filter((node) => node.type === "a").length, 1, "only preview citation content can be focusable while collapsed");

const expandedOrientationModule = loadComponent(orientationSource, "OrientationSummary.tsx", {
  "@/lib/orientationPresentation": {
    previewOrientationQuestion: (question: string) => question,
    visibleOrientationActions: () => ({ primary: null, secondary: [] }),
    actionOwnerText: () => null,
    actionStateWord: () => "Ready",
  },
}, [false, true]);
const expandedTree = expandedOrientationModule.default!({
  question: { question_id: "Q-2", revision: "q2", text: "May the service launch?" }, shortAnswer: supportedOpening, reviewItems: [], allIssueCount: 1,
  onOpenIssue: () => undefined, onShowAllIssues: () => undefined,
  renderAnswer: (answer: string) => jsx("div", { children: answer }),
});
const expandedText = textContent(expandedTree);
assert.equal(expandedText.includes("Later analysis must stay below the fold"), true, "expansion mounts the complete saved answer");
assert.match(expandedText, /Show shorter answer/, "the expanded answer can return to the compact view");

const hugeSingleBlock = "One very long continuous answer without sentence punctuation ".repeat(30).trim();
const hugePreview = compactAnswerPreview(hugeSingleBlock);
assert.equal(hugePreview.shortened, true);
assert.equal(hugePreview.plainText, true, "a huge single block uses a safe plain-text preview instead of broken Markdown");
assert.ok(hugePreview.text.length <= 421 && hugePreview.text.endsWith("…"), "the huge single-block preview is bounded at a word boundary");
let hugeRendererCalls = 0;
const hugeTree = OrientationSummary({
  question: { question_id: "Q-3", revision: "q3", text: "What is the answer?" }, shortAnswer: hugeSingleBlock, reviewItems: [], allIssueCount: 0,
  onOpenIssue: () => undefined, onShowAllIssues: () => undefined,
  renderAnswer: () => { hugeRendererCalls += 1; return jsx("a", { href: "#hidden", children: "hidden full answer" }); },
});
assert.equal(hugeRendererCalls, 0, "a truncated single block does not mount hidden focusable source links");
assert.equal((children(hugeTree) as ElementNode[]).some((node) => node.type === "a"), false, "no full-answer link remains focusable in the collapsed single-block tree");

const legacyTree = OrientationSummary({
  orientation: null,
  loading: false,
  error: null,
  onOpenTarget: () => undefined,
  onRefresh: () => undefined,
});
assert.equal(textContent(legacyTree).includes("Saved orientation is unavailable"), true, "existing continuity callers keep the legacy rendering path");

for (const source of [workItemSource, orientationSource]) {
  assert.doesNotMatch(source, /#[0-9a-fA-F]{3,8}/, "review presentation uses shared semantic tokens only");
  assert.doesNotMatch(source, /minWidth:\s*["']?[4-9][0-9]{2}/, "review presentation has no fixed desktop minimum width");
}

console.log("Review render and callback checks passed. Browser width checks remain pending.");

frontend/scripts/check-transport-preserv:
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { AutoLinkNode, LinkNode } from "@lexical/link";
import { ListItemNode, ListNode } from "@lexical/list";
import {
  $convertFromMarkdownString,
  $convertToMarkdownString,
  BOLD_ITALIC_STAR,
  BOLD_STAR,
  BOLD_UNDERSCORE,
  HEADING,
  ITALIC_STAR,
  ITALIC_UNDERSCORE,
  LINK,
  ORDERED_LIST,
  QUOTE,
  UNORDERED_LIST,
} from "@lexical/markdown";
import { HeadingNode, QuoteNode } from "@lexical/rich-text";
import { $getRoot, $getSelection, $isRangeSelection, createEditor } from "lexical";
import { remainingComposerValue } from "../lib/chatRunLogic.ts";
import {
  discardLocalEditorSnapshot,
  documentVersionKey,
  freezeDocumentTarget,
  localEditorSnapshotStorageKey,
  mutationBasisForSnapshot,
  readLocalEditorSnapshot,
  recoverableLocalEditorSnapshot,
  sameDocumentTarget,
  snapshotForDocument,
  writeLocalEditorSnapshot,
} from "../lib/documentNavigation.ts";
import { isModifiedDocumentEnd, moveSelectionToDocumentEnd } from "../lib/editorSelection.ts";
import { savedMarkdownMatches } from "../lib/documentSave.ts";

const form = readFileSync(new URL("../components/NewMatterForm.tsx", import.meta.url), "utf8");
const api = readFileSync(new URL("../lib/api.ts", import.meta.url), "utf8");
const panel = readFileSync(new URL("../components/DocumentPanel.tsx", import.meta.url), "utf8");
const editor = readFileSync(new URL("../components/MarkdownRichEditor.tsx", import.meta.url), "utf8");
const apiModel = readFileSync(new URL("../../backend/app/models/api.py", import.meta.url), "utf8");
const matterService = readFileSync(new URL("../../backend/app/services/matters.py", import.meta.url), "utf8");
const chatPanel = readFileSync(new URL("../components/ChatPanel.tsx", import.meta.url), "utf8");
const chatCards = readFileSync(new URL("../components/ChatCards.tsx", import.meta.url), "utf8");

assert.match(form, /const submittedTargetDate = matterTargetDateFromForm\(new FormData\(event\.currentTarget\)\);[\s\S]*await getSettings\(\)[\s\S]*target_date:\s*submittedTargetDate/, "the matter payload must use the submitted target date captured from FormData before any await");
assert.doesNotMatch(form, /target_date:\s*targetDate(?:\s*\|\|\s*null)?/, "matter creation must not fall back to stale target-date React state");
assert.match(form, /type="date"[\s\S]*value=\{targetDate\}/, "the target-date input must remain controlled");
assert.match(api, /createMatter[\s\S]+JSON\.stringify\(payload\)/, "the matters API must transport the full form payload");
assert.match(apiModel, /class MatterCreate[\s\S]+target_date:\s*str\s*\|\s*None\s*=\s*None/, "the API model must accept a target date");
assert.match(matterService, /"target_date":\s*request\.target_date/, "the matter record must store the target date");
assert.match(matterService, /"requested_launch_date":\s*request\.target_date/, "the immutable request must store the target date");
assert.match(chatPanel, /setMessages\(\(current\) => \[\.\.\.current, \{ role: "user"/, "chat must echo a submitted user turn before transport completes");
assert.match(chatPanel, /setInput\(\(current\) => remainingComposerValue/, "accepted submissions must clear only the composer text they sent");
assert.equal(
  remainingComposerValue("Unsent question", "Unsent question", false, ""),
  "Unsent question",
  "a failed or unrelated submission must preserve composer text",
);
assert.equal(
  remainingComposerValue("Newer unsent question", "Submitted question", true, ""),
  "Newer unsent question",
