    if (name === "react/jsx-runtime") return { Fragment: "Fragment", jsx, jsxs: jsx };
    if (name === "react") return { useEffect: () => undefined, useMemo: (fn: () => unknown) => fn(), useRef: (value: unknown) => ({ current: value }), useState: (value: unknown) => [value, () => undefined] };
